package com.buildpreview;

import java.awt.event.KeyEvent;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(BuildPreviewConfig.GROUP)
public interface BuildPreviewConfig extends Config
{
	String GROUP = "buildpreview";

	@ConfigItem(keyName = "opacity", name = "Preview opacity", description = "How solid the preview is. Less than fully solid makes it plain that it is not built yet", position = 0)
	@Units(Units.PERCENT)
	@Range(min = 20, max = 100)
	default int opacity()
	{
		return 70;
	}

	@ConfigItem(keyName = "hideHotspot", name = "Hide the hotspot", description = "Hide the empty hotspot's placeholder while a preview stands on it. Needs the GPU or 117 HD plugin; without one the placeholder stays", position = 1)
	default boolean hideHotspot()
	{
		return true;
	}

	@ConfigItem(keyName = "keepLast", name = "Keep the last preview", description = "Keep showing the last furniture hovered while the mouse is between entries, rather than clearing it", position = 2)
	default boolean keepLast()
	{
		return true;
	}

	@ConfigItem(keyName = "keepAfterClose", name = "Keep after closing the menu", description = "Leave the preview standing when the build menu is closed, so it can be looked at from any angle. It goes when something is built there, Build is chosen elsewhere, or the clear key is pressed", position = 3)
	default boolean keepAfterClose()
	{
		return true;
	}

	@ConfigItem(keyName = "previousKey", name = "Previous furniture", description = "With the menu closed, show the furniture before this one in the hotspot's list", position = 4)
	default Keybind previousKey()
	{
		return new Keybind(KeyEvent.VK_PAGE_UP, 0);
	}

	@ConfigItem(keyName = "nextKey", name = "Next furniture", description = "With the menu closed, show the furniture after this one in the hotspot's list", position = 5)
	default Keybind nextKey()
	{
		return new Keybind(KeyEvent.VK_PAGE_DOWN, 0);
	}

	@ConfigItem(keyName = "clearKey", name = "Clear preview", description = "Take the preview down", position = 6)
	default Keybind clearKey()
	{
		return new Keybind(KeyEvent.VK_DELETE, 0);
	}

	@ConfigItem(keyName = "showName", name = "Show the name", description = "Label the preview with the furniture's name, its place in the list and the keys that change it", position = 7)
	default boolean showName()
	{
		return true;
	}
}

package com.buildpreview;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/** Names the furniture being previewed, just above where it stands. */
class BuildPreviewOverlay extends Overlay
{
	/** How far above the floor the label sits, in the game's height units. */
	private static final int LABEL_HEIGHT = 160;
	private static final Color LABEL = new Color(255, 230, 160);

	private final Client client;
	private final BuildPreviewPlugin plugin;

	@Inject
	BuildPreviewOverlay(Client client, BuildPreviewPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		String text = plugin.label();
		LocalPoint anchor = plugin.labelAnchor();
		if (text == null || anchor == null || plugin.labelLevel() != client.getTopLevelWorldView().getPlane())
		{
			return null;
		}
		Point at = Perspective.getCanvasTextLocation(client, graphics, anchor, text, LABEL_HEIGHT);
		if (at != null)
		{
			OverlayUtil.renderTextLocation(graphics, at, text, LABEL);
		}
		return null;
	}
}

package com.buildpreview;

import com.google.inject.Provides;
import java.awt.Point;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.GroundObject;
import net.runelite.api.ItemComposition;
import net.runelite.api.MenuAction;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

/**
 * Shows furniture standing on its hotspot before it is built. Choosing Build on a hotspot opens the
 * game's build menu; while it is open, whichever furniture the mouse is over is drawn where it would
 * stand, slightly see-through. Nothing is sent to the game and no menu is changed: the plugin only
 * notices the Build click, reads the menu, and draws a model of its own.
 */
@Slf4j
@PluginDescriptor(
	name = "Build Preview",
	description = "See furniture in place in your house before you build it, by hovering it in the build menu",
	tags = {"construction", "poh", "house", "build", "furniture", "preview", "hotspot"}
)
public class BuildPreviewPlugin extends Plugin
{
	private static final int[] MENU_ROOTS = {
		InterfaceID.PohFurnitureCreation.UNIVERSE,
		InterfaceID.PohFurnitureCreationMenu.UNIVERSE,
	};

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private BuildPreviewConfig config;
	@Inject private RenderCallbackManager renderCallbackManager;
	@Inject private KeyManager keyManager;
	@Inject private OverlayManager overlayManager;
	@Inject private BuildPreviewOverlay overlay;

	private FurnitureIndex furniture;
	private MenuReader menuReader;
	private final Map<Integer, Model> models = new HashMap<>();

	/** The hotspot Build was last chosen on, where it was found, and where a preview there goes. */
	private TileObject hotspot;
	private int hotspotWorldView;
	private int hotspotSceneX;
	private int hotspotSceneY;
	private LocalPoint anchor;
	private int anchorLevel;
	private int orientation;

	private RuneLiteObject preview;
	private int previewItem = -1;
	/**
	 * The hash of the hotspot to leave undrawn, or NONE. GPU renderers such as 117 HD draw on their
	 * own threads, so the render callback reads only this; it must not touch the client.
	 */
	private static final long NONE = -1L;
	private volatile long hiddenHotspot = NONE;
	private boolean menuWasOpen;
	private boolean menuDescribed;
	/** The hotspot's furniture in menu order, so the keys can step through it with the menu closed. */
	private final List<Integer> options = new ArrayList<>();

	private final HotkeyListener previousKey = stepper(() -> config.previousKey(), -1);
	private final HotkeyListener nextKey = stepper(() -> config.nextKey(), 1);
	private final HotkeyListener clearKey = new HotkeyListener(() -> config.clearKey())
	{
		@Override
		public void hotkeyPressed()
		{
			clientThread.invoke(() ->
			{
				clearPreview();
				forgetHotspot();
			});
		}
	};

	private final RenderCallback hideHotspot = new RenderCallback()
	{
		@Override
		public boolean drawObject(Scene scene, TileObject object)
		{
			// Only while a preview stands on it; the hotspot is otherwise left exactly as it was.
			long hidden = hiddenHotspot;
			return hidden == NONE || object.getHash() != hidden;
		}
	};

	@Override
	protected void startUp()
	{
		furniture = new FurnitureIndex(client);
		menuReader = new MenuReader(furniture);
		renderCallbackManager.register(hideHotspot);
		keyManager.registerKeyListener(previousKey);
		keyManager.registerKeyListener(nextKey);
		keyManager.registerKeyListener(clearKey);
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		renderCallbackManager.unregister(hideHotspot);
		keyManager.unregisterKeyListener(previousKey);
		keyManager.unregisterKeyListener(nextKey);
		keyManager.unregisterKeyListener(clearKey);
		overlayManager.remove(overlay);
		// The preview is part of the scene; take it down on the thread that draws the scene.
		clientThread.invoke(() ->
		{
			clearPreview();
			forgetHotspot();
			models.clear();
		});
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		// Only noticed, never changed: this is the click that opens the build menu.
		String option = event.getMenuOption();
		if (option == null || !(option.equalsIgnoreCase("Build") || option.equalsIgnoreCase("Upgrade")))
		{
			return;
		}
		if (!isObjectOption(event.getMenuAction()))
		{
			return;
		}
		int worldView = event.getMenuEntry().getWorldViewId();
		TileObject found = findObject(worldView, event.getParam0(), event.getParam1(), event.getId());
		clearPreview();
		forgetHotspot();
		if (found == null)
		{
			log.debug("Build Preview could not find hotspot {} at {},{}", event.getId(), event.getParam0(), event.getParam1());
			return;
		}
		hotspotWorldView = worldView;
		hotspotSceneX = event.getParam0();
		hotspotSceneY = event.getParam1();
		remember(found);
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (hotspot == null)
		{
			return;
		}
		Widget menu = openMenu();
		if (menu == null)
		{
			if (menuWasOpen)
			{
				menuWasOpen = false;
				// Closing the menu leaves the preview to be looked at from anywhere, unless that is
				// turned off. If something was built, the next game tick finds the hotspot gone.
				if (!config.keepAfterClose() || preview == null)
				{
					clearPreview();
					forgetHotspot();
				}
			}
			return;
		}
		if (!menuWasOpen)
		{
			menuWasOpen = true;
			if (!menuDescribed)
			{
				menuDescribed = true;
				menuReader.describe(menu);
			}
		}

		List<Integer> shown = menuReader.all(menu);
		if (!shown.isEmpty() && !shown.equals(options))
		{
			options.clear();
			options.addAll(shown);
		}

		net.runelite.api.Point canvas = client.getMouseCanvasPosition();
		Point mouse = canvas == null ? null : new Point(canvas.getX(), canvas.getY());
		int item = menuReader.hovered(menu, mouse);
		if (item <= 0)
		{
			if (!config.keepLast())
			{
				clearPreview();
			}
			return;
		}
		if (item != previewItem || preview == null)
		{
			show(item);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Building on the hotspot replaces it, and leaving build mode takes it away. Either way a
		// preview standing there has nothing left to show.
		if (hotspot != null && openMenu() == null
			&& findObject(hotspotWorldView, hotspotSceneX, hotspotSceneY, hotspot.getId()) == null)
		{
			clearPreview();
			forgetHotspot();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Leaving the house, hopping or logging out unloads the scene the hotspot belonged to.
		if (event.getGameState() == GameState.LOADING || event.getGameState() == GameState.LOGIN_SCREEN
			|| event.getGameState() == GameState.HOPPING)
		{
			clearPreview();
			forgetHotspot();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!BuildPreviewConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		// Opacity is baked into the models; build them again at the new strength.
		clientThread.invoke(() ->
		{
			models.clear();
			int item = previewItem;
			clearPreview();
			if (item > 0 && hotspot != null)
			{
				show(item);
			}
		});
	}

	private Widget openMenu()
	{
		for (int id : MENU_ROOTS)
		{
			Widget root = client.getWidget(id);
			if (root != null && !root.isHidden())
			{
				return root;
			}
		}
		return null;
	}

	private void show(int item)
	{
		Model model = model(item);
		if (model == null)
		{
			// The model may not have loaded yet; the next frame asks again.
			return;
		}
		if (preview == null)
		{
			preview = client.createRuneLiteObject();
		}
		preview.setModel(model);
		preview.setLocation(anchor, anchorLevel);
		preview.setZ(hotspot.getZ());
		preview.setOrientation(orientation);
		preview.setActive(true);
		previewItem = item;
		hiddenHotspot = config.hideHotspot() ? hotspot.getHash() : NONE;
		log.debug("Build Preview showing {} ({})", furniture.nameOf(item), item);
	}

	/** The furniture's model, recoloured as its menu item is and made see-through. */
	private Model model(int item)
	{
		Model cached = models.get(item);
		if (cached != null)
		{
			return cached;
		}
		ItemComposition definition = client.getItemDefinition(item);
		if (definition == null || definition.getInventoryModel() <= 0)
		{
			return null;
		}
		ModelData base = client.loadModelData(definition.getInventoryModel());
		if (base == null)
		{
			return null;
		}
		// A copy with its own colour and transparency arrays, so the cached original is untouched. Most
		// furniture has no textures at all, and there is no texture array to copy then.
		ModelData data = base.shallowCopy().cloneColors().cloneTransparencies(true);
		recolour(data, definition.getColorToReplace(), definition.getColorToReplaceWith(), false);
		if (data.getFaceTextures() != null)
		{
			data.cloneTextures();
			recolour(data, definition.getTextureToReplace(), definition.getTextureToReplaceWith(), true);
		}
		byte[] transparencies = data.getFaceTransparencies();
		int wanted = PreviewMath.transparencyForOpacity(config.opacity());
		if (transparencies != null && wanted > 0)
		{
			for (int i = 0; i < transparencies.length; i++)
			{
				transparencies[i] = PreviewMath.blendTransparency(transparencies[i], wanted);
			}
		}
		Model model = data.light();
		if (model != null)
		{
			models.put(item, model);
		}
		return model;
	}

	private static void recolour(ModelData data, short[] from, short[] to, boolean textures)
	{
		if (from == null || to == null)
		{
			return;
		}
		for (int i = 0; i < Math.min(from.length, to.length); i++)
		{
			if (textures)
			{
				data.retexture(from[i], to[i]);
			}
			else
			{
				data.recolor(from[i], to[i]);
			}
		}
	}

	/** Where furniture built on this hotspot stands, facing the way the hotspot faces. */
	private void remember(TileObject object)
	{
		hotspot = object;
		anchorLevel = object.getPlane();
		LocalPoint location = object.getLocalLocation();
		int rotation;
		if (object instanceof GameObject)
		{
			orientation = ((GameObject) object).getOrientation();
			rotation = -1;
		}
		else if (object instanceof WallObject)
		{
			rotation = PreviewMath.rotationFromConfig(((WallObject) object).getConfig());
		}
		else if (object instanceof DecorativeObject)
		{
			DecorativeObject decor = (DecorativeObject) object;
			rotation = PreviewMath.rotationFromConfig(decor.getConfig());
			// Wall decorations sit a little off the wall line; the furniture sits where the space does.
			location = new LocalPoint(location.getX() + decor.getXOffset(), location.getY() + decor.getYOffset(),
				location.getWorldView());
		}
		else if (object instanceof GroundObject)
		{
			rotation = PreviewMath.rotationFromConfig(((GroundObject) object).getConfig());
		}
		else
		{
			rotation = 0;
		}
		if (rotation >= 0)
		{
			orientation = PreviewMath.orientationForRotation(rotation);
		}
		anchor = location;
		menuWasOpen = false;
		log.debug("Build Preview hotspot {} at {} orientation {}", object.getId(), anchor, orientation);
	}

	private void forgetHotspot()
	{
		hotspot = null;
		anchor = null;
		menuWasOpen = false;
		options.clear();
	}

	private HotkeyListener stepper(java.util.function.Supplier<net.runelite.client.config.Keybind> key, int direction)
	{
		return new HotkeyListener(key)
		{
			@Override
			public void hotkeyPressed()
			{
				clientThread.invoke(() -> step(direction));
			}
		};
	}

	/** Shows the furniture before or after the current one in the hotspot's list. */
	private void step(int direction)
	{
		if (hotspot == null || options.isEmpty())
		{
			return;
		}
		int next = PreviewMath.step(options.indexOf(previewItem), direction, options.size());
		if (next >= 0)
		{
			show(options.get(next));
		}
	}

	/** What the overlay labels the preview with, or null for no label. Client thread. */
	String label()
	{
		if (!config.showName() || preview == null || previewItem <= 0)
		{
			return null;
		}
		String name = furniture == null ? null : furniture.nameOf(previewItem);
		if (name == null)
		{
			return null;
		}
		int index = options.indexOf(previewItem);
		String place = index >= 0 ? " (" + (index + 1) + "/" + options.size() + ")" : "";
		String keys = openMenu() == null && options.size() > 1
			? "  " + config.previousKey() + " / " + config.nextKey() : "";
		return name + place + keys;
	}

	LocalPoint labelAnchor()
	{
		return preview == null ? null : anchor;
	}

	int labelLevel()
	{
		return anchorLevel;
	}

	private void clearPreview()
	{
		hiddenHotspot = NONE;
		if (preview != null)
		{
			preview.setActive(false);
			preview = null;
		}
		previewItem = -1;
	}

	private TileObject findObject(int worldViewId, int sceneX, int sceneY, int objectId)
	{
		WorldView view = worldViewId >= 0 ? client.getWorldView(worldViewId) : null;
		if (view == null)
		{
			view = client.getTopLevelWorldView();
		}
		if (view == null)
		{
			return null;
		}
		Tile[][][] tiles = view.getScene().getTiles();
		int plane = view.getPlane();
		if (plane < 0 || plane >= tiles.length || sceneX < 0 || sceneX >= tiles[plane].length
			|| sceneY < 0 || sceneY >= tiles[plane][sceneX].length)
		{
			return null;
		}
		Tile tile = tiles[plane][sceneX][sceneY];
		if (tile == null)
		{
			return null;
		}
		for (GameObject object : tile.getGameObjects())
		{
			if (object != null && object.getId() == objectId)
			{
				return object;
			}
		}
		if (tile.getWallObject() != null && tile.getWallObject().getId() == objectId)
		{
			return tile.getWallObject();
		}
		if (tile.getDecorativeObject() != null && tile.getDecorativeObject().getId() == objectId)
		{
			return tile.getDecorativeObject();
		}
		if (tile.getGroundObject() != null && tile.getGroundObject().getId() == objectId)
		{
			return tile.getGroundObject();
		}
		return null;
	}

	private static boolean isObjectOption(MenuAction action)
	{
		return action == MenuAction.GAME_OBJECT_FIRST_OPTION || action == MenuAction.GAME_OBJECT_SECOND_OPTION
			|| action == MenuAction.GAME_OBJECT_THIRD_OPTION || action == MenuAction.GAME_OBJECT_FOURTH_OPTION
			|| action == MenuAction.GAME_OBJECT_FIFTH_OPTION;
	}

	@Provides
	BuildPreviewConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BuildPreviewConfig.class);
	}
}

package com.buildpreview;

import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;

/**
 * Every piece of furniture the game can build, read from its own construction table: the name the
 * build menu shows and the item whose model the menu draws. That model is the furniture's own, so
 * it is also what the preview draws. Client thread only.
 */
@Slf4j
class FurnitureIndex
{
	private final Client client;
	private final Map<Integer, String> namesByItem = new HashMap<>();
	private final Map<String, Integer> itemsByName = new HashMap<>();
	private boolean loaded;

	FurnitureIndex(Client client)
	{
		this.client = client;
	}

	boolean isFurniture(int itemId)
	{
		load();
		return itemId > 0 && namesByItem.containsKey(itemId);
	}

	/** The menu item for a furniture name as the build menu prints it, or -1. */
	int itemForName(String name)
	{
		load();
		Integer item = itemsByName.get(key(name));
		return item == null ? -1 : item;
	}

	String nameOf(int itemId)
	{
		load();
		return namesByItem.get(itemId);
	}

	void clear()
	{
		namesByItem.clear();
		itemsByName.clear();
		loaded = false;
	}

	private void load()
	{
		if (loaded)
		{
			return;
		}
		loaded = true;
		List<Integer> rows = client.getDBTableRows(DBTableID.Furniture.ID);
		if (rows == null)
		{
			return;
		}
		for (int row : rows)
		{
			Object[] item = client.getDBTableField(row, DBTableID.Furniture.COL_MODEL_OBJ, 0);
			Object[] name = client.getDBTableField(row, DBTableID.Furniture.COL_NAME, 0);
			if (item == null || item.length == 0 || !(item[0] instanceof Integer))
			{
				continue;
			}
			int itemId = (Integer) item[0];
			String text = name != null && name.length > 0 && name[0] instanceof String ? (String) name[0] : null;
			if (text == null)
			{
				continue;
			}
			namesByItem.put(itemId, text);
			// Two rows can share a name (an upgrade path, say); the first is as good as any.
			itemsByName.putIfAbsent(key(text), itemId);
		}
		log.debug("Build Preview read {} furniture rows", namesByItem.size());
	}

	private static String key(String name)
	{
		return PreviewMath.plainText(name).toLowerCase(Locale.ROOT);
	}
}

package com.buildpreview;

import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModelType;

/**
 * Works out which furniture in the game's build menu the mouse is over, by reading the menu's
 * widgets. It only reads them; nothing in the menu is changed. Client thread only.
 */
@Slf4j
class MenuReader
{
	private final FurnitureIndex furniture;

	MenuReader(FurnitureIndex furniture)
	{
		this.furniture = furniture;
	}

	/** The menu item of the furniture under the mouse in this menu, or -1 when it is over none. */
	int hovered(Widget root, Point mouse)
	{
		if (root == null || root.isHidden() || mouse == null)
		{
			return -1;
		}
		List<Widget> path = new ArrayList<>();
		deepestPath(root, mouse, path);
		// From the widget under the mouse outwards: the first one that holds exactly one piece of
		// furniture is that furniture's entry. Holding several means this is the list itself, and the
		// row level with the mouse is the one meant.
		for (int i = path.size() - 1; i >= 0; i--)
		{
			Map<Integer, Rectangle> found = new LinkedHashMap<>();
			collect(path.get(i), found);
			if (found.size() == 1)
			{
				return found.keySet().iterator().next();
			}
			if (found.size() > 1)
			{
				List<PreviewMath.Candidate> candidates = new ArrayList<>();
				found.forEach((item, bounds) -> candidates.add(new PreviewMath.Candidate(item, bounds)));
				PreviewMath.Candidate row = PreviewMath.pickByRow(candidates, mouse);
				return row == null ? -1 : row.itemId;
			}
		}
		return -1;
	}

	/** Every furniture choice the menu offers, top to bottom and left to right. */
	List<Integer> all(Widget root)
	{
		List<Integer> items = new ArrayList<>();
		if (root == null || root.isHidden())
		{
			return items;
		}
		Map<Integer, Rectangle> found = new LinkedHashMap<>();
		collect(root, found);
		List<PreviewMath.Candidate> candidates = new ArrayList<>();
		found.forEach((item, bounds) -> candidates.add(new PreviewMath.Candidate(item, bounds)));
		for (PreviewMath.Candidate candidate : PreviewMath.inReadingOrder(candidates))
		{
			items.add(candidate.itemId);
		}
		return items;
	}

	/** Walks down to the deepest visible widget under the mouse, recording the way. */
	private static void deepestPath(Widget widget, Point mouse, List<Widget> path)
	{
		if (widget == null || widget.isHidden())
		{
			return;
		}
		Rectangle bounds = widget.getBounds();
		if (bounds == null || !bounds.contains(mouse))
		{
			return;
		}
		path.add(widget);
		// Later children are drawn over earlier ones, so the last that contains the mouse is on top.
		Widget next = null;
		for (Widget[] children : childLists(widget))
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				if (child != null && !child.isHidden() && child.getBounds() != null && child.getBounds().contains(mouse))
				{
					next = child;
				}
			}
		}
		if (next != null)
		{
			deepestPath(next, mouse, path);
		}
	}

	/** Every piece of furniture shown anywhere inside this widget, with the area it covers. */
	private void collect(Widget widget, Map<Integer, Rectangle> found)
	{
		if (widget == null || widget.isHidden())
		{
			return;
		}
		int item = furnitureShownBy(widget);
		if (item > 0)
		{
			Rectangle bounds = widget.getBounds();
			Rectangle known = found.get(item);
			found.put(item, known == null ? bounds : bounds == null ? known : known.union(bounds));
		}
		for (Widget[] children : childLists(widget))
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				collect(child, found);
			}
		}
	}

	/** The furniture a single widget shows: as a model of its menu item, or by name. */
	private int furnitureShownBy(Widget widget)
	{
		int item = widget.getItemId();
		if (item <= 0 && widget.getModelType() == WidgetModelType.ITEM)
		{
			item = widget.getModelId();
		}
		if (item > 0 && furniture.isFurniture(item))
		{
			return item;
		}
		String text = widget.getText();
		if (text != null && !text.isEmpty())
		{
			return furniture.itemForName(text);
		}
		return -1;
	}

	private static Widget[][] childLists(Widget widget)
	{
		return new Widget[][] {widget.getStaticChildren(), widget.getDynamicChildren(), widget.getNestedChildren()};
	}

	/** Writes the menu's widgets to the debug log once, so a layout this does not read can be fixed. */
	void describe(Widget root)
	{
		if (root == null || !log.isDebugEnabled())
		{
			return;
		}
		StringBuilder out = new StringBuilder("Build menu widgets:");
		describe(root, 0, out);
		log.debug(out.toString());
	}

	private void describe(Widget widget, int depth, StringBuilder out)
	{
		if (widget == null || depth > 12)
		{
			return;
		}
		out.append('\n');
		for (int i = 0; i < depth; i++)
		{
			out.append("  ");
		}
		out.append(widget.getId() >> 16).append(':').append(widget.getId() & 0xFFFF)
			.append(" type=").append(widget.getType())
			.append(widget.isHidden() ? " hidden" : "")
			.append(" item=").append(widget.getItemId())
			.append(" model=").append(widget.getModelType()).append('/').append(widget.getModelId())
			.append(" bounds=").append(widget.getBounds());
		String text = widget.getText();
		if (text != null && !text.isEmpty())
		{
			out.append(" text='").append(text).append('\'');
		}
		for (Widget[] children : childLists(widget))
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				describe(child, depth + 1, out);
			}
		}
	}
}

package com.buildpreview;

import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** The arithmetic of a preview, kept apart from the client so it can be tested. */
final class PreviewMath
{
	/** A quarter turn in the game's angle units, where a full turn is 2048. */
	static final int QUARTER_TURN = 512;

	private PreviewMath()
	{
	}

	/**
	 * The rotation a placed object was given, out of its scene config. Bits 6 and 7 hold quarter
	 * turns; the low five bits hold the object's shape.
	 */
	static int rotationFromConfig(int config)
	{
		return (config >> 6) & 3;
	}

	/** Quarter turns to the angle units a RuneLite object is oriented in. */
	static int orientationForRotation(int rotation)
	{
		return (rotation & 3) * QUARTER_TURN;
	}

	/**
	 * The transparency to give every face for a preview this opaque, in the game's terms: 0 is
	 * solid, 255 is invisible. A face that is already more see-through than that keeps its own.
	 */
	static int transparencyForOpacity(int opacityPercent)
	{
		int clamped = Math.max(0, Math.min(100, opacityPercent));
		return Math.round((100 - clamped) * 255 / 100f);
	}

	static byte blendTransparency(byte existing, int wanted)
	{
		int own = existing & 0xFF;
		return (byte) Math.max(own, wanted);
	}

	/** One furniture choice in the build menu and the part of the screen it was drawn in. */
	static final class Candidate
	{
		final int itemId;
		final Rectangle bounds;

		Candidate(int itemId, Rectangle bounds)
		{
			this.itemId = itemId;
			this.bounds = bounds;
		}
	}

	/**
	 * When the mouse is over a part of the menu shared by several choices, the row it is level with
	 * is the one meant. Returns the candidate whose bounds span the mouse's height, nearest the mouse
	 * across if more than one does, or null when none is level with it.
	 */
	static Candidate pickByRow(List<Candidate> candidates, Point mouse)
	{
		Candidate best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (Candidate candidate : candidates)
		{
			Rectangle b = candidate.bounds;
			if (b == null || mouse.y < b.y || mouse.y >= b.y + b.height)
			{
				continue;
			}
			int distance = mouse.x < b.x ? b.x - mouse.x : mouse.x >= b.x + b.width ? mouse.x - (b.x + b.width - 1) : 0;
			if (distance < bestDistance)
			{
				best = candidate;
				bestDistance = distance;
			}
		}
		return best;
	}

	/** Candidates in the order they are read: by row, then across. Ones without bounds go last. */
	static List<Candidate> inReadingOrder(List<Candidate> candidates)
	{
		List<Candidate> sorted = new ArrayList<>(candidates);
		sorted.sort(Comparator
			.comparingInt((Candidate c) -> c.bounds == null ? Integer.MAX_VALUE : c.bounds.y)
			.thenComparingInt(c -> c.bounds == null ? Integer.MAX_VALUE : c.bounds.x));
		return sorted;
	}

	/** The index {@code step} places on from {@code index} in a list of {@code size}, wrapping round. */
	static int step(int index, int step, int size)
	{
		if (size <= 0)
		{
			return -1;
		}
		if (index < 0)
		{
			return step >= 0 ? 0 : size - 1;
		}
		return Math.floorMod(index + step, size);
	}

	/** Strips the colour and formatting tags the game puts in widget text. */
	static String plainText(String text)
	{
		if (text == null)
		{
			return "";
		}
		return text.replaceAll("<[^>]*>", "").replace(' ', ' ').trim();
	}
}

