package com.buildpreview;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class PreviewMathTest
{
	@Test
	public void rotationComesFromBitsSixAndSeven()
	{
		// Shape 10 (a centrepiece), each quarter turn.
		assertEquals(0, PreviewMath.rotationFromConfig(10));
		assertEquals(1, PreviewMath.rotationFromConfig(10 | 1 << 6));
		assertEquals(2, PreviewMath.rotationFromConfig(10 | 2 << 6));
		assertEquals(3, PreviewMath.rotationFromConfig(10 | 3 << 6));
		// Higher bits do not leak in.
		assertEquals(1, PreviewMath.rotationFromConfig(0xFF00 | 1 << 6));
	}

	@Test
	public void quarterTurnsBecomeAngles()
	{
		assertEquals(0, PreviewMath.orientationForRotation(0));
		assertEquals(512, PreviewMath.orientationForRotation(1));
		assertEquals(1024, PreviewMath.orientationForRotation(2));
		assertEquals(1536, PreviewMath.orientationForRotation(3));
		assertEquals(512, PreviewMath.orientationForRotation(5));
	}

	@Test
	public void opacityBecomesTransparency()
	{
		assertEquals(0, PreviewMath.transparencyForOpacity(100));
		assertEquals(255, PreviewMath.transparencyForOpacity(0));
		assertEquals(77, PreviewMath.transparencyForOpacity(70));
		assertEquals(0, PreviewMath.transparencyForOpacity(150));
		assertEquals(255, PreviewMath.transparencyForOpacity(-5));
	}

	@Test
	public void aFaceKeepsItsOwnTransparencyWhenClearer()
	{
		assertEquals(77, PreviewMath.blendTransparency((byte) 0, 77) & 0xFF);
		assertEquals(200, PreviewMath.blendTransparency((byte) 200, 77) & 0xFF);
		assertEquals(77, PreviewMath.blendTransparency((byte) 40, 77) & 0xFF);
	}

	@Test
	public void theRowLevelWithTheMouseIsPicked()
	{
		PreviewMath.Candidate top = new PreviewMath.Candidate(1, new Rectangle(10, 10, 100, 30));
		PreviewMath.Candidate middle = new PreviewMath.Candidate(2, new Rectangle(10, 40, 100, 30));
		PreviewMath.Candidate bottom = new PreviewMath.Candidate(3, new Rectangle(10, 70, 100, 30));
		// Over the middle row, even out to the side of it.
		assertEquals(2, PreviewMath.pickByRow(Arrays.asList(top, middle, bottom), new Point(50, 55)).itemId);
		assertEquals(2, PreviewMath.pickByRow(Arrays.asList(top, middle, bottom), new Point(300, 55)).itemId);
		// Between rows and below them all.
		assertNull(PreviewMath.pickByRow(Arrays.asList(top, middle, bottom), new Point(50, 200)));
		assertNull(PreviewMath.pickByRow(Collections.emptyList(), new Point(50, 55)));
	}

	@Test
	public void twoColumnsOnOneRowPickTheNearer()
	{
		PreviewMath.Candidate left = new PreviewMath.Candidate(1, new Rectangle(0, 0, 100, 30));
		PreviewMath.Candidate right = new PreviewMath.Candidate(2, new Rectangle(200, 0, 100, 30));
		assertEquals(1, PreviewMath.pickByRow(Arrays.asList(left, right), new Point(120, 10)).itemId);
		assertEquals(2, PreviewMath.pickByRow(Arrays.asList(left, right), new Point(180, 10)).itemId);
		assertEquals(2, PreviewMath.pickByRow(Arrays.asList(left, right), new Point(250, 10)).itemId);
	}

	@Test
	public void choicesAreReadByRowThenAcross()
	{
		PreviewMath.Candidate a = new PreviewMath.Candidate(1, new Rectangle(200, 0, 10, 10));
		PreviewMath.Candidate b = new PreviewMath.Candidate(2, new Rectangle(0, 0, 10, 10));
		PreviewMath.Candidate c = new PreviewMath.Candidate(3, new Rectangle(0, 50, 10, 10));
		PreviewMath.Candidate d = new PreviewMath.Candidate(4, null);
		java.util.List<PreviewMath.Candidate> sorted = PreviewMath.inReadingOrder(Arrays.asList(d, c, a, b));
		assertEquals(2, sorted.get(0).itemId);
		assertEquals(1, sorted.get(1).itemId);
		assertEquals(3, sorted.get(2).itemId);
		assertEquals(4, sorted.get(3).itemId);
	}

	@Test
	public void steppingWrapsRound()
	{
		assertEquals(1, PreviewMath.step(0, 1, 3));
		assertEquals(0, PreviewMath.step(2, 1, 3));
		assertEquals(2, PreviewMath.step(0, -1, 3));
		// Nothing chosen yet: forwards starts at the top, backwards at the bottom.
		assertEquals(0, PreviewMath.step(-1, 1, 3));
		assertEquals(2, PreviewMath.step(-1, -1, 3));
		assertEquals(-1, PreviewMath.step(0, 1, 0));
	}

	@Test
	public void menuTextLosesItsTags()
	{
		assertEquals("Teak armchair", PreviewMath.plainText("<col=ffffff>Teak armchair</col>"));
		assertEquals("Oak chair", PreviewMath.plainText("  Oak chair "));
		assertEquals("", PreviewMath.plainText(null));
	}
}
